function user(): ?array { return $_SESSION['user'] ?? null; }
function require_login(): array { if(!user()) redirect('page=login'); $sid=q('SELECT session_id FROM users WHERE id=?',[user()['id']])->fetchColumn(); if($sid&&$sid!==session_id()){session_destroy();session_start();flash('danger','Akun Anda telah login di perangkat lain.');redirect('page=login');} return user(); }
function role(string ...$roles): array { $u=require_login(); if(!in_array($u['role'],$roles,true)){ http_response_code(403); exit('Akses ditolak.'); } return $u; }
function q(string $sql,array $p=[]): PDOStatement { $s=db()->prepare($sql); $s->execute($p); return $s; }
function log_action(string $action): void { if(user()) q('INSERT INTO logs(user_id,action) VALUES(?,?)',[user()['id'],$action]); }
function notify(int $userId, string $title, string $message = '', string $type = 'info'): void { q('INSERT INTO notifications(user_id,title,message,type) VALUES(?,?,?,?)',[$userId,$title,$message,$type]); }
function student_email_domain(?int $classId = null): string { if($classId){ $code=q('SELECT m.code FROM classes c JOIN majors m ON m.id=c.major_id WHERE c.id=?',[$classId])->fetchColumn(); if($code) return 'smkjp1.'.strtolower($code).'.id'; } $d=q('SELECT setting_value FROM settings WHERE setting_key="student_email_domain"')->fetchColumn(); return $d?:'school.local'; }
function roman_grade(string $name): string { return preg_replace_callback('/^(10|11|12)(?=\s|$)/', fn($m) => ['10'=>'X','11'=>'XI','12'=>'XII'][$m[1]], trim($name)); }

