if($action==='monitor_data'){$u=role('Admin','Guru','Proktor');$eid=(int)$_GET['exam_id'];$tid=$u['role']==='Guru'?q('SELECT id FROM teachers WHERE user_id=?',[$u['id']])->fetchColumn():null;if($tid&&!q('SELECT id FROM exams WHERE id=? AND teacher_id=?',[$eid,$tid])->fetch()){header('Content-Type: application/json');echo json_encode([]);exit;}$results=q('SELECT r.id,r.status,r.score,r.started_at,r.last_ping,r.ping_count,st.user_id,u.name student_name, (SELECT COUNT(*) FROM answers a WHERE a.result_id=r.id) answered, (SELECT COUNT(*) FROM violations v WHERE v.result_id=r.id) violations FROM exam_results r JOIN students st ON st.id=r.student_id JOIN users u ON u.id=st.user_id WHERE r.exam_id=? ORDER BY u.name',[$eid])->fetchAll(PDO::FETCH_ASSOC);$totalQ=q('SELECT COUNT(*) FROM exam_questions WHERE exam_id=?',[$eid])->fetchColumn();$threshold=time()-30;foreach($results as &$x){$x['total_questions']=(int)$totalQ;$x['online']=$x['last_ping']&&strtotime($x['last_ping'])>=$threshold?1:0;$x['started_at']=$x['started_at']??'';$x['last_ping']=$x['last_ping']??'';}header('Content-Type: application/json');echo json_encode($results);exit;}
if($action==='submit'&&$_SERVER['REQUEST_METHOD']==='POST'){ $u=role('Siswa');verify_csrf();$rid=(int)$_POST['result'];$own=q('SELECT r.id,r.exam_id,r.started_at,e.duration FROM exam_results r JOIN students s ON s.id=r.student_id JOIN exams e ON e.id=r.exam_id WHERE r.id=? AND s.user_id=? AND r.status="in_progress"',[$rid,$u['id']])->fetch(PDO::FETCH_ASSOC);if(!$own){flash('danger','Ujian tidak ditemukan atau sudah dikumpulkan.');redirect('page=student');} if(time()>strtotime($own['started_at'])+$own['duration']*60){q("INSERT INTO violations(result_id,type) VALUES(?,?)",[$rid,'time_expired']);grade_result($rid);flash('danger','Waktu ujian telah habis. Jawaban dikumpulkan otomatis.');redirect('page=student');} grade_result($rid);$exam=q('SELECT e.teacher_id,e.title FROM exam_results r JOIN exams e ON e.id=r.exam_id WHERE r.id=?',[$rid])->fetch(PDO::FETCH_ASSOC);if($exam['teacher_id']){$tu=q('SELECT user_id FROM teachers WHERE id=?',[$exam['teacher_id']])->fetchColumn();if($tu)notify($tu,'Siswa mengumpulkan ujian',$u['name'].' mengumpulkan "'.$exam['title'].'"','info');}flash('success','Ujian berhasil dikumpulkan.');redirect('page=student');}
function grade_result(int $rid):void{$r=q('SELECT * FROM exam_results WHERE id=?',[$rid])->fetch(PDO::FETCH_ASSOC);if(!$r||$r['status']!=='in_progress')return;$sq=q('SELECT question_id FROM student_questions WHERE result_id=?',[$rid])->fetchAll(PDO::FETCH_COLUMN);if($sq){$pl=implode(',',array_fill(0,count($sq),'?'));$qs=q("SELECT q.* FROM questions q WHERE q.id IN ($pl)",$sq)->fetchAll(PDO::FETCH_ASSOC);}else{$qs=q('SELECT q.* FROM exam_questions eq JOIN questions q ON q.id=eq.question_id WHERE eq.exam_id=?',[$r['exam_id']])->fetchAll(PDO::FETCH_ASSOC);}$earned=0;$total=0;$essay=false;foreach($qs as $x){$total+=(float)$x['weight'];if($x['type']==='essay'){$essay=true;continue;}$a=q('SELECT answer_text FROM answers WHERE result_id=? AND question_id=?',[$rid,$x['id']])->fetchColumn();$correct=q('SELECT label FROM choices WHERE question_id=? AND is_correct=1',[$x['id']])->fetchColumn();$ok=$a===$correct;$earned+=$ok?(float)$x['weight']:0;q('UPDATE answers SET is_correct=?,score=? WHERE result_id=? AND question_id=?',[$ok?1:0,$ok?$x['weight']:0,$rid,$x['id']]);}$score=$total?round($earned/$total*100,2):0;q('UPDATE exam_results SET submitted_at=NOW(),status=?,score=? WHERE id=?',[$essay?'submitted':'graded',$score,$rid]);}
if($action==='export'){$u=role('Admin','Guru');$tid=$u['role']==='Guru'?q('SELECT id FROM teachers WHERE user_id=?',[$u['id']])->fetchColumn():null;$sql='SELECT u.name siswa,e.title ujian,r.score,r.status,r.started_at,r.submitted_at FROM exam_results r JOIN students s ON s.id=r.student_id JOIN users u ON u.id=s.user_id JOIN exams e ON e.id=r.exam_id';$params=[];if($tid){$sql.=' WHERE e.teacher_id=?';$params[]=$tid;}$sql.=' ORDER BY r.id DESC';$rows=q($sql,$params)->fetchAll(PDO::FETCH_ASSOC);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename=laporan-nilai.csv');$o=fopen('php://output','w');fputcsv($o,['Siswa','Ujian','Nilai','Status','Mulai','Selesai']);foreach($rows as $x)fputcsv($o,$x);exit;}
if($action==='toggle_active'&&$_SERVER['REQUEST_METHOD']==='POST'){ role('Admin');verify_csrf();$entity=$_POST['entity']??'';$id=(int)($_POST['id']??0);if(in_array($entity,['users','exams'],true)&&$id){q("UPDATE $entity SET active=1-active WHERE id=?",[$id]);flash('success','Status diperbarui.');}redirect('page='.($entity==='users'?'users':'exams'));}
if($action==='profile_save'&&$_SERVER['REQUEST_METHOD']==='POST'){$u=require_login();verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));if($name===''||$email===''){flash('danger','Nama dan email tidak boleh kosong.');redirect('page=profile');}$dup=q('SELECT id FROM users WHERE email=? AND id!=?',[$email,$u['id']])->fetchColumn();if($dup){flash('danger','Email sudah digunakan user lain.');redirect('page=profile');}q('UPDATE users SET name=?,email=? WHERE id=?',[$name,$email,$u['id']]);$u2=q('SELECT u.*,r.name role FROM users u JOIN roles r ON r.id=u.role_id WHERE u.id=?',[$u['id']])->fetch(PDO::FETCH_ASSOC);$_SESSION['user']=$u2;log_action('Ubah profil');flash('success','Profil berhasil diperbarui.');redirect('page=profile');}
if($action==='password_save'&&$_SERVER['REQUEST_METHOD']==='POST'){$u=require_login();verify_csrf();$old=$_POST['old_password']??'';$new=$_POST['new_password']??'';$confirm=$_POST['confirm_password']??'';if(strlen($new)<6){flash('danger','Password baru minimal 6 karakter.');redirect('page=profile');}if($new!==$confirm){flash('danger','Konfirmasi password tidak cocok.');redirect('page=profile');}$s=q('SELECT password FROM users WHERE id=?',[$u['id']])->fetchColumn();if(!password_verify($old,$s)){flash('danger','Password lama salah.');redirect('page=profile');}q('UPDATE users SET password=? WHERE id=?',[password_hash($new,PASSWORD_DEFAULT),$u['id']]);log_action('Ubah password');flash('success','Password berhasil diubah.');redirect('page=profile');}
if($action==='settings_save'&&$_SERVER['REQUEST_METHOD']==='POST'){role('Admin');verify_csrf();foreach($_POST as $k=>$v){if(str_starts_with($k,'key_')){$key=substr($k,4);q('INSERT INTO settings(setting_key,setting_value) VALUES(?,?) ON DUPLICATE KEY UPDATE setting_value=?',[$key,$v,$v]);}}flash('success','Pengaturan disimpan.');redirect('page=settings');}
if($action==='grade_save'&&$_SERVER['REQUEST_METHOD']==='POST'){$u=role('Admin','Guru');verify_csrf();$rid=(int)$_POST['result_id'];$tid=$u['role']==='Guru'?q('SELECT id FROM teachers WHERE user_id=?',[$u['id']])->fetchColumn():null;$r=q('SELECT r.*,e.teacher_id,e.title exam_title FROM exam_results r JOIN exams e ON e.id=r.exam_id WHERE r.id=? AND r.status="submitted"',[$rid])->fetch(PDO::FETCH_ASSOC);if(!$r||($tid&&$r['teacher_id']!=$tid)){flash('danger','Akses ditolak.');redirect('page=grading');}$essayScores=[];foreach($_POST as $k=>$v){if(str_starts_with($k,'score_'))$essayScores[(int)substr($k,6)]=(float)$v;}$sq=q('SELECT question_id FROM student_questions WHERE result_id=?',[$rid])->fetchAll(PDO::FETCH_COLUMN);$total=0;$earned=0;if($sq){$pl=implode(',',array_fill(0,count($sq),'?'));$sqParams=array_merge($sq,$sq);$qs=q("SELECT q.id,q.weight FROM questions q WHERE q.id IN ($pl) AND q.type='essay' ORDER BY FIELD(q.id,$pl)",$sqParams)->fetchAll(PDO::FETCH_ASSOC);}else{$qs=q('SELECT q.id,q.weight FROM exam_questions eq JOIN questions q ON q.id=eq.question_id WHERE q.type="essay" AND eq.exam_id=?',[$r['exam_id']])->fetchAll(PDO::FETCH_ASSOC);}foreach($qs as $q){$w=(float)$q['weight'];$total+=$w;$s=$essayScores[$q['id']]??0;$s=min($s,$w);$earned+=$s;q('UPDATE answers SET score=?,is_correct=? WHERE result_id=? AND question_id=?',[$s,$s>0?1:0,$rid,$q['id']]);}$multipleTotal=0;$multipleEarned=0;if($sq){$mq=q("SELECT q.id,q.weight FROM questions q WHERE q.id IN ($pl) AND q.type='multiple' ORDER BY FIELD(q.id,$pl)",$sqParams)->fetchAll(PDO::FETCH_ASSOC);}else{$mq=q('SELECT q.id,q.weight FROM exam_questions eq JOIN questions q ON q.id=eq.question_id WHERE q.type="multiple" AND eq.exam_id=?',[$r['exam_id']])->fetchAll(PDO::FETCH_ASSOC);}foreach($mq as $q){$multipleTotal+=(float)$q['weight'];$a=q('SELECT score FROM answers WHERE result_id=? AND question_id=?',[$rid,$q['id']])->fetchColumn();$multipleEarned+=(float)$a;}$finalTotal=$total+$multipleTotal;$finalEarned=$earned+$multipleEarned;$score=$finalTotal?round($finalEarned/$finalTotal*100,2):0;q('UPDATE exam_results SET status="graded",score=? WHERE id=?',[$score,$rid]);log_action('Koreksi essay result #'.$rid);$su=q('SELECT s.user_id FROM exam_results r JOIN students s ON s.id=r.student_id WHERE r.id=?',[$rid])->fetchColumn();if($su)notify($su,'Nilai sudah keluar','Nilai ujian "'.$r['exam_title'].'": '.$score,'grade');flash('success','Nilai essay disimpan. Nilai akhir: '.$score);redirect('page=grading&exam_id='.$r['exam_id']);}
if($action==='get_notifications'){require_login();$count=q('SELECT COUNT(*) FROM notifications WHERE user_id=? AND is_read=0',[user()['id']])->fetchColumn();$list=q('SELECT id,title,message,type,created_at FROM notifications WHERE user_id=? ORDER BY created_at DESC LIMIT 5',[user()['id']])->fetchAll(PDO::FETCH_ASSOC);header('Content-Type: application/json');echo json_encode(['count'=>(int)$count,'list'=>$list]);exit;}
