if($action==='download_result'){$u=role('Siswa');$rid=(int)$_GET['result'];$r=q('SELECT r.*,e.title,e.duration,s.name subject_name,sc.name class_name,u2.name teacher_name FROM exam_results r JOIN exams e ON e.id=r.exam_id JOIN subjects s ON s.id=e.subject_id LEFT JOIN teachers t ON t.id=e.teacher_id LEFT JOIN users u2 ON u2.id=t.user_id JOIN students st ON st.id=r.student_id JOIN users u3 ON u3.id=st.user_id LEFT JOIN classes sc ON sc.id=st.class_id WHERE r.id=? AND st.user_id=? AND r.status IN("submitted","graded")',[$rid,$u['id']])->fetch(PDO::FETCH_ASSOC);if(!$r)redirect('page=student');$sq=q('SELECT question_id FROM student_questions WHERE result_id=?',[$rid])->fetchAll(PDO::FETCH_COLUMN);if($sq){$pl=implode(',',array_fill(0,count($sq),'?'));$qs=q("SELECT q.* FROM questions q WHERE q.id IN ($pl) ORDER BY FIELD(q.id,$pl)",array_merge($sq,$sq))->fetchAll(PDO::FETCH_ASSOC);}else{$qs=q('SELECT q.* FROM exam_questions eq JOIN questions q ON q.id=eq.question_id WHERE eq.exam_id=? ORDER BY q.id',[$r['exam_id']])->fetchAll(PDO::FETCH_ASSOC);}?><!doctype html><html lang="id"><head><meta charset="utf-8"><title>Hasil Ujian - <?=e($r['title'])?></title><style>body{font-family:sans-serif;padding:40px;color:#111}h2{margin:0}table{width:100%;border-collapse:collapse;margin:20px 0}th,td{padding:8px 12px;text-align:left;border:1px solid #ddd}th{background:#f5f5f5}.score{font-size:32px;font-weight:700;color:#4f46e5}.footer{margin-top:30px;font-size:12px;color:#999;text-align:center}@media print{body{padding:20px}}</style></head><body><div style="display:flex;justify-content:space-between;align-items:center;border-bottom:2px solid #4f46e5;padding-bottom:16px;margin-bottom:24px"><div><h2><?=e($r['title'])?></h2><small><?=e($r['subject_name'])?> | <?=e($r['class_name']??'-')?> | <?=e($r['teacher_name']??'-')?></small></div><div class="score"><?=$r['score']??'-'?></div></div><table><tr><th>Nama</th><td><?=e($u['name'])?></td><th>Durasi</th><td><?=$r['duration']?> menit</td></tr><tr><th>Status</th><td><?=$r['status']==='graded'?'Dinilai':'Menunggu Koreksi'?></td><th>Selesai</th><td><?=$r['submitted_at']??'-'?></td></tr></table><table><thead><tr><th>#</th><th>Soal</th><th>Jawaban</th><th>Benar</th><th>Skor</th></tr></thead><tbody><?php foreach($qs as $n=>$x):$a=q('SELECT a.*,c.label cl FROM answers a LEFT JOIN choices c ON c.question_id=a.question_id AND c.is_correct=1 WHERE a.result_id=? AND a.question_id=?',[$rid,$x['id']])->fetch(PDO::FETCH_ASSOC);?><tr><td><?=$n+1?></td><td><?=e(mb_strimwidth($x['question'],0,100,'...'))?></td><td><?=e($a['answer_text']??'-')?></td><td><?php if($x['type']==='multiple'):?><?=e($a['cl']??'-')?><?php else:?>-<?php endif?></td><td><?=$a['score']!==null?$a['score'].'/'.$x['weight']:($x['type']==='essay'?'Menunggu':'-')?></td></tr><?php endforeach?></tbody></table><div class="footer">Dicetak dari <?=APP_NAME?> &mdash; <?=date('d/m/Y H:i')?></div><script>window.print()</script></body></html><?php exit;}
